//! DRT gate (M1-11, docs/13): the ACES 2 output transform against OpenColorIO vectors.
//!
//! `tests/data/aces2/<output>.json` holds AP0 inputs and OpenColorIO's float32 output for each of
//! the four outputs (generated by `tools/vectors/aces2_vectors.py`). The gate is at most one code
//! value at 10 bits (|ours - expected| * 1023 <= 1) for every channel of every vector. Run with
//! `-- --nocapture` to see the per-output maximum and 99th percentile.

use serde_json::Value;
use ym_color::aces2::{Aces2Output, Aces2Transform};

/// Gate: 1 code value at 10 bits.
const GATE_CODE_VALUES_10BIT: f64 = 1.0;
const CODE_VALUES_10BIT: f64 = 1023.0;

struct Vectors {
    ocio_version: String,
    group_names: Vec<(String, usize, usize)>,
    input: Vec<[f64; 3]>,
    encoded: Vec<[f64; 3]>,
    linear: Vec<[f64; 3]>,
}

fn triplets(v: &Value) -> Vec<[f64; 3]> {
    v.as_array()
        .expect("array of triplets")
        .iter()
        .map(|row| {
            let r = row.as_array().expect("triplet");
            // The values are float32 numbers written as their shortest decimal; recover the f32.
            let f = |i: usize| r[i].as_f64().expect("number") as f32 as f64;
            [f(0), f(1), f(2)]
        })
        .collect()
}

fn load(output: Aces2Output) -> Vectors {
    let path = format!(
        "{}/tests/data/aces2/{}.json",
        env!("CARGO_MANIFEST_DIR"),
        output.name()
    );
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {path}: {e}"));
    let doc: Value = serde_json::from_str(&text).expect("valid JSON");
    assert_eq!(doc["schema"], "yellowmoon/aces2-vectors/1");
    assert_eq!(doc["output"], output.name());
    assert_eq!(doc["peak_luminance_nits"], 100);
    let group_names = doc["groups"]
        .as_array()
        .expect("groups")
        .iter()
        .map(|g| {
            (
                g["name"].as_str().expect("name").to_string(),
                g["start"].as_u64().expect("start") as usize,
                g["count"].as_u64().expect("count") as usize,
            )
        })
        .collect();
    let v = Vectors {
        ocio_version: doc["ocio"]["version"]
            .as_str()
            .expect("ocio version")
            .to_string(),
        group_names,
        input: triplets(&doc["input_ap0"]),
        encoded: triplets(&doc["expected_encoded"]),
        linear: triplets(&doc["expected_display_linear"]),
    };
    assert_eq!(
        v.input.len(),
        doc["count"].as_u64().expect("count") as usize
    );
    assert_eq!(v.encoded.len(), v.input.len());
    assert_eq!(v.linear.len(), v.input.len());
    v
}

fn group_of(v: &Vectors, index: usize) -> &str {
    v.group_names
        .iter()
        .find(|(_, start, count)| index >= *start && index < start + count)
        .map(|(name, _, _)| name.as_str())
        .unwrap_or("?")
}

struct Stats {
    max: f64,
    max_index: usize,
    p99: f64,
    mean: f64,
}

/// Error of each vector: max over channels, in 10-bit code values.
fn stats(errors: &[f64]) -> Stats {
    let mut sorted = errors.to_vec();
    sorted.sort_by(|a, b| a.partial_cmp(b).expect("no NaN"));
    let (max_index, max) = errors
        .iter()
        .copied()
        .enumerate()
        .fold((0, 0.0), |acc, (i, e)| if e > acc.1 { (i, e) } else { acc });
    let p99 = sorted[((sorted.len() as f64) * 0.99).ceil() as usize - 1];
    Stats {
        max,
        max_index,
        p99,
        mean: errors.iter().sum::<f64>() / errors.len() as f64,
    }
}

fn code_error(a: [f64; 3], b: [f64; 3]) -> f64 {
    (0..3)
        .map(|k| (a[k] - b[k]).abs() * CODE_VALUES_10BIT)
        .fold(0.0, f64::max)
}

fn run_gate(output: Aces2Output) {
    let v = load(output);
    let t = Aces2Transform::new(output);

    let mut enc_err = Vec::with_capacity(v.input.len());
    let mut raw_err = Vec::with_capacity(v.input.len());
    let mut lin_err = Vec::with_capacity(v.input.len());
    for i in 0..v.input.len() {
        // The API promises [0, 1]. Ten-bit code values cannot exceed 1.0 either, so the gate
        // compares against the reference clamped the same way.
        let ours = t.transform_ap0(v.input[i]);
        assert!(
            ours.iter()
                .all(|c| c.is_finite() && (0.0..=1.0).contains(c)),
            "vector {i}: {ours:?}"
        );
        let expected_clamped = v.encoded[i].map(|c| c.clamp(0.0, 1.0));
        enc_err.push(code_error(ours, expected_clamped));

        // Strict check against the raw reference (OCIO leaves Rec.2020 cyan up to 3.4e-4 above 1.0).
        raw_err.push(code_error(
            t.transform_ap0_unclamped(v.input[i]),
            v.encoded[i].map(|c| c.max(0.0)),
        ));

        // Display-linear, compared after encoding so the tolerance is in code values as well.
        let ours_lin = t.transform_ap0_linear(v.input[i]);
        lin_err.push(code_error(
            t.encode_display_linear(ours_lin),
            t.encode_display_linear(v.linear[i]),
        ));
    }

    let s = stats(&enc_err);
    let r = stats(&raw_err);
    let l = stats(&lin_err);
    println!(
        "{:<11} OCIO {}: {} vectors, encoded max {:.4} (#{}, {}) p99 {:.4} mean {:.5} | unclamped max {:.4} p99 {:.4} | display-linear max {:.4} p99 {:.4} (10-bit code values)",
        output.name(),
        v.ocio_version,
        v.input.len(),
        s.max,
        s.max_index,
        group_of(&v, s.max_index),
        s.p99,
        s.mean,
        r.max,
        r.p99,
        l.max,
        l.p99
    );

    assert!(
        s.max <= GATE_CODE_VALUES_10BIT,
        "{}: worst vector #{} ({}) input {:?} ours {:?} expected {:?}: {:.4} code values",
        output.name(),
        s.max_index,
        group_of(&v, s.max_index),
        v.input[s.max_index],
        t.transform_ap0(v.input[s.max_index]),
        v.encoded[s.max_index],
        s.max
    );
    assert!(
        r.max <= GATE_CODE_VALUES_10BIT,
        "{}: unclamped {:.4} code values (#{})",
        output.name(),
        r.max,
        r.max_index
    );
    assert!(
        l.max <= GATE_CODE_VALUES_10BIT,
        "{}: display-linear {:.4} code values (#{})",
        output.name(),
        l.max,
        l.max_index
    );
}

#[test]
fn viewport_matches_ocio() {
    run_gate(Aces2Output::Viewport);
}

#[test]
fn srgb_matches_ocio() {
    run_gate(Aces2Output::Srgb);
}

#[test]
fn display_p3_matches_ocio() {
    run_gate(Aces2Output::DisplayP3);
}

#[test]
fn rec2020_matches_ocio() {
    run_gate(Aces2Output::Rec2020);
}
